// problogtut_basic_10_inhibitioneffects_1.pl: a ProbLog program written in Psi by tddlog's scripts/problog2ppl.py,
// first order as it is written. A relation is a column of integers for each
// argument and a column of Booleans for whether each tuple holds, a symbol a
// number of its own; each probabilistic fact is a coin of its own (`flip`), the
// facts arrays in the program; each rule is a loop over the relations its body
// joins, a tuple looked up by a scan. The value is the array of the queries'
// holdings, given the evidence (`observe`): one is asked a run, its `return`
// made `return queries[K];`.
//
//   psi --dp PROGRAM.psi
def main() {
  // c1/0: 1 facts
  c1__facts_p := [0.5]: ℝ[];
  c1__facts_h := array(c1__facts_p.length, false);
  for i in [0..c1__facts_p.length) { if c1__facts_p[i] < 1 { c1__facts_h[i] = flip(c1__facts_p[i]); } else { c1__facts_h[i] = true; } }
  // c2/0: 1 facts
  c2__facts_p := [0.5]: ℝ[];
  c2__facts_h := array(c2__facts_p.length, false);
  for i in [0..c2__facts_p.length) { if c2__facts_p[i] < 1 { c2__facts_h[i] = flip(c2__facts_p[i]); } else { c2__facts_h[i] = true; } }

  c1__h := c1__facts_h;

  c2__h := c2__facts_h;

  e_h := []: 𝔹[];
  // 0.3::e :- c1.
  for k1 in [0..c1__h.length) {
    x2 := c1__h[k1];
    c3 := flip(0.3);
    v4 := x2 && c3;
    f5 := false;
    for k6 in [0..e_h.length) {
      if true { e_h[k6] = e_h[k6] || v4; f5 = true; }
    }
    if !f5 { e_h = e_h ~ [v4]; }
  }
  // 0.4::e :- c2.
  for k7 in [0..c2__h.length) {
    x8 := c2__h[k7];
    c9 := flip(0.4);
    v10 := x8 && c9;
    f11 := false;
    for k12 in [0..e_h.length) {
      if true { e_h[k12] = e_h[k12] || v10; f11 = true; }
    }
    if !f11 { e_h = e_h ~ [v10]; }
  }

  q13 := false;
  for q13_k in [0..e_h.length) { if true { q13 = e_h[q13_k]; } }
  e14 := false;
  for e14_k in [0..c1__h.length) { if true { e14 = c1__h[e14_k]; } }
  e15 := false;
  for e15_k in [0..c2__h.length) { if true { e15 = c2__h[e15_k]; } }
  observe(e14 && e15);
  queries := [q13];
  return queries[0];
}

